import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
const evidence = { phases: [], networkAttempts: 0, preconnectAttempts: 0, cwd: process.cwd() };
const denyFetch = async () => { evidence.networkAttempts++; throw new Error('TASK24_NETWORK_DISABLED'); };
denyFetch.preconnect = () => { evidence.preconnectAttempts++; throw new Error('TASK24_PRECONNECT_DISABLED'); };
globalThis.fetch = denyFetch;
let authStorage;
let session;
try {
  const sdk = await import('@oh-my-pi/pi-coding-agent');
  evidence.phases.push('installed-public-root-imported');
  evidence.entries = Object.fromEntries(['@oh-my-pi/pi-coding-agent','@oh-my-pi/pi-coding-agent/sdk','@oh-my-pi/pi-natives','@oh-my-pi/pi-ai','@oh-my-pi/pi-utils'].map(name => [name, fs.realpathSync(Bun.resolveSync(name, process.cwd()))]));
  for (const file of Object.values(evidence.entries)) if (!file.startsWith(path.join(process.cwd(),'node_modules') + path.sep)) throw new Error('ENTRY_OUTSIDE_INSTALLED_CONSUMER');
  const natives = await import('@oh-my-pi/pi-natives');
  evidence.native = { tokenCount: natives.countTokens('Hello world!'), visibleWidth: natives.visibleWidth('oh-my-pi', 2), diff: natives.diffLines('line 1\n', 'line 1\nline 2\n') };
  const nativeDir = path.dirname(evidence.entries['@oh-my-pi/pi-natives']);
  const loader = await import(path.join(nativeDir,'loader-state.js'));
  const ctx = loader.initLoaderContext();
  evidence.native.loaderStatus = loader.nativeAddonStatus();
  if (ctx) evidence.native.workspaceLoad = ctx.isWorkspaceLoad;
  const addonPath = evidence.native.loaderStatus?.path;
  if (!addonPath || !fs.realpathSync(addonPath).startsWith(path.join(process.cwd(),'node_modules') + path.sep)) throw new Error('ADDON_OUTSIDE_INSTALLED_CONSUMER');
  evidence.native.addonSha256 = createHash('sha256').update(fs.readFileSync(addonPath)).digest('hex');
  evidence.phases.push('real-native-operations-returned');
  const docs = await import('@oh-my-pi/pi-coding-agent/internal-urls/docs-index');
  const filenames = docs.getDocFilenames();
  const body = filenames.length ? await docs.getEmbeddedDoc(filenames[0]) : undefined;
  evidence.docs = { count: filenames.length, firstName: filenames[0], firstBodyBytes: body ? Buffer.byteLength(body) : 0 };
  if (!evidence.docs.count || !evidence.docs.firstBodyBytes) throw new Error('INSTALLED_DOCS_NOT_LOADED');
  const cwd = path.join(process.cwd(),'workspace');
  fs.mkdirSync(cwd, {recursive:true});
  const agentDir = process.env.PI_CODING_AGENT_DIR;
  const dbPath = path.join(agentDir,'agent.db');
  evidence.auth = { selectedPath: dbPath, existedBefore: fs.existsSync(dbPath) };
  authStorage = await sdk.AuthStorage.create(dbPath);
  const stat = fs.statSync(dbPath);
  evidence.auth.mode = (stat.mode & 0o777).toString(8);
  evidence.auth.regularFile = stat.isFile();
  evidence.auth.ownedByEffectiveUser = stat.uid === process.geteuid();
  const settings = sdk.Settings.isolated({'secrets.enabled':false}, {storage:null});
  const modelRegistry = new sdk.ModelRegistry(authStorage,path.join(agentDir,'models.yml'), {ignoreLocalModelConfig:true,settings,cacheDbPath:':memory:',fetch:denyFetch});
  const sessionManager = sdk.SessionManager.inMemory(cwd);
  const agentRegistry = new sdk.AgentRegistry();
  const result = await sdk.createAgentSession({cwd,agentDir,settings,authStorage,modelRegistry,sessionManager,agentRegistry,skills:[],rules:[],promptTemplates:[],slashCommands:[],contextFiles:[],workspaceTree:{rootPath:cwd,rendered:'',truncated:false,totalLines:0,agentsMdFiles:[]},disableExtensionDiscovery:true,additionalExtensionPaths:[],enableMCP:false,enableLsp:false,skipPythonPreflight:true,cacheWarming:false,bindProcessState:false});
  session = result.session;
  evidence.factory = { created: session instanceof sdk.AgentSession, sessionManagerRetained: session.sessionManager === sessionManager, modelSelected: Boolean(session.model) };
  evidence.phases.push('actual-public-factory-created');
  await session.dispose();
  session = undefined;
  evidence.factory.disposed = true;
  evidence.phases.push('actual-session-disposed');
  authStorage.close(); authStorage = undefined;
  evidence.auth.closed = true;
  evidence.phases.push('caller-owned-auth-closed');
  evidence.status = evidence.networkAttempts === 0 && evidence.preconnectAttempts === 0 ? 'passed' : 'network-attempt-blocked';
} catch (error) {
  evidence.status = 'failed';
  evidence.error = {name:error?.name,message:String(error?.message ?? error),stack:String(error?.stack ?? '').split('\n').slice(0,8)};
} finally {
  if (session) { try { await session.dispose(); evidence.cleanupSessionDisposed = true; } catch { evidence.cleanupSessionDisposed = false; } }
  if (authStorage) { try { authStorage.close(); evidence.cleanupAuthClosed = true; } catch { evidence.cleanupAuthClosed = false; } }
  fs.writeFileSync(path.join(process.cwd(),'runtime-result.json'),JSON.stringify(evidence,null,2)+'\n');
  console.log(JSON.stringify(evidence));
}
if (evidence.status !== 'passed') process.exitCode = 1;
